import React, { useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { XMarkIcon, EyeIcon, EyeSlashIcon } from '@heroicons/react/24/outline';
import { loginUser, registerUser } from '../../store/slices/authSlice';
import { AppDispatch } from '../../store';
import CustomSelect from '../CustomSelect/CustomSelect';
import { useLanguage } from '../../contexts/LanguageContext';
import { captchaPrompt, checkMathCaptcha, generateMathCaptcha, MathCaptchaChallenge, normalizeDigits } from '../../utils/mathCaptcha';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialMode?: 'login' | 'register';
  /** When true, stay on current page after login/register (e.g. booking checkout) */
  stayOnPage?: boolean;
}

const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, initialMode = 'login', stayOnPage = false }) => {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [showTermsModal, setShowTermsModal] = useState(false); // ✨ نمایش مودال شرایط
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const location = useLocation();
  const { t, language } = useLanguage();

  const shouldStayOnPage =
    stayOnPage ||
    /\/booking|\/payment/i.test(location.pathname);

  // Login form
  const [loginForm, setLoginForm] = useState({
    nationalId: '',
    password: '',
    captcha: ''
  });

  // Register form — passenger identity + contact required at signup
  const [registerForm, setRegisterForm] = useState({
    nationality: 'iranian',
    nationalId: '',
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    birthDate: '',
    password: '',
    confirmPassword: '',
    captcha: ''
  });

  const isValidEmail = (email: string) =>
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());

  const normalizePhone = (raw: string) => {
    let phone = raw.replace(/[\s\-]/g, '');
    if (phone.startsWith('+98')) phone = `0${phone.slice(3)}`;
    else if (phone.startsWith('0098')) phone = `0${phone.slice(4)}`;
    else if (phone.startsWith('98') && phone.length === 12) phone = `0${phone.slice(2)}`;
    return phone;
  };

  const isValidIranPhone = (raw: string) => /^09\d{9}$/.test(normalizePhone(raw));

  // Captcha — non-negative, Persian-digit safe
  const [captcha, setCaptcha] = useState<MathCaptchaChallenge>(() => generateMathCaptcha());
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const generateCaptcha = () => {
    setCaptcha(generateMathCaptcha());
  };

  useEffect(() => {
    if (isOpen) {
      generateCaptcha();
      setError('');
      setSuccess('');
      setLoginForm((prev) => ({ ...prev, captcha: '' }));
      setRegisterForm((prev) => ({ ...prev, captcha: '' }));
    }
  }, [isOpen]);

  useEffect(() => {
    setMode(initialMode);
  }, [initialMode]);

  const validateNationalId = (nationalId: string): boolean => {
    if (nationalId.length !== 10) return false;
    const check = parseInt(nationalId[9]);
    let sum = 0;
    for (let i = 0; i < 9; i++) {
      sum += parseInt(nationalId[i]) * (10 - i);
    }
    const remainder = sum % 11;
    return (remainder < 2 && check === remainder) || (remainder >= 2 && check === 11 - remainder);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Validate captcha (instant, local — no network)
    if (!checkMathCaptcha(loginForm.captcha, captcha.answer)) {
      setError(t('auth.captchaError'));
      generateCaptcha();
      setLoginForm(prev => ({ ...prev, captcha: '' }));
      return;
    }

    const input = loginForm.nationalId.trim();
    
    // اگر حاوی @ باشد = ایمیل (کاربری که ایمیلش رو در پروفایل عوض کرده)
    const isEmail = input.includes('@');
    
    if (isEmail) {
      // اعتبارسنجی ساده ایمیل
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(input)) {
        setError(language === 'fa' ? 'فرمت ایمیل نامعتبر است' : language === 'ar' ? 'تنسيق البريد الإلكتروني غير صالح' : 'Invalid email format');
        return;
      }
    } else {
      // کد ملی یا شماره پاسپورت
      const isNationalId = /^\d{10}$/.test(input);
      const isPassportNumber = /^[A-Z0-9]{6,20}$/.test(input);
      
      if (!isNationalId && !isPassportNumber) {
        if (input.length === 10 && !isNationalId) {
          setError(t('auth.invalidNationalId'));
        } else {
          setError(t('auth.nationalIdOrPassportInvalid'));
        }
        return;
      }
      
      if (isNationalId && !validateNationalId(input)) {
        setError(t('auth.invalidNationalId'));
        return;
      }
    }

    setShowTermsModal(true);
  };

  // ✨ لاگین پس از موافقت با شرایط
  const handleAgreeLoginTerms = async () => {
    setShowTermsModal(false);
    setError('');

    const input = loginForm.nationalId.trim();
    // بک‌اند با کد ملی، پاسپورت، یا ایمیل جستجو می‌کند - همان مقدار خام را می‌فرستیم
    try {
      await dispatch(loginUser({
        email: input,
        password: loginForm.password
      })).unwrap();
      
      setSuccess(t('auth.loginSuccess'));
      setTimeout(() => {
        onClose();
        if (!shouldStayOnPage) {
          navigate('/dashboard');
        }
      }, 1000);
    } catch (err: any) {
      setError(typeof err === 'string' ? err : (err?.message || t('auth.loginError')));
      generateCaptcha();
      setLoginForm((prev) => ({ ...prev, captcha: '' }));
    }
  };

  // ✨ نمایش مودال شرایط قبل از ثبت‌نام
  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!checkMathCaptcha(registerForm.captcha, captcha.answer)) {
      setError(t('auth.captchaError'));
      generateCaptcha();
      setRegisterForm(prev => ({ ...prev, captcha: '' }));
      return;
    }

    if (registerForm.firstName.trim().length < 2) {
      setError(t('auth.firstNameRequired'));
      return;
    }
    if (registerForm.lastName.trim().length < 2) {
      setError(t('auth.lastNameRequired'));
      return;
    }
    if (!isValidEmail(registerForm.email)) {
      setError(t('auth.invalidEmail'));
      return;
    }
    if (!isValidIranPhone(registerForm.phone)) {
      setError(t('auth.invalidPhone'));
      return;
    }

    // Validate national ID (only for Iranian nationality)
    if (registerForm.nationality === 'iranian' && !validateNationalId(registerForm.nationalId)) {
      setError(t('auth.invalidNationalId'));
      return;
    }
    
    // Basic validation for passport number (for non-Iranian)
    if (registerForm.nationality !== 'iranian' && registerForm.nationalId.length < 6) {
      setError(t('auth.invalidPassport'));
      return;
    }

    // Validate passwords match
    if (registerForm.password !== registerForm.confirmPassword) {
      setError(t('auth.passwordMismatch'));
      return;
    }

    // Validate password strength
    if (registerForm.password.length < 8) {
      setError(t('auth.passwordMinLength'));
      return;
    }

    // Validate birth date
    const today = new Date();
    const birthDate = new Date(registerForm.birthDate);
    const age = today.getFullYear() - birthDate.getFullYear();
    if (age < 18) {
      setError(t('auth.ageRestriction'));
      return;
    }

    // ✨ نمایش مودال شرایط قبل از ثبت‌نام
    setShowTermsModal(true);
  };

  // ✨ ثبت‌نام پس از موافقت با شرایط
  const handleAgreeTerms = async () => {
    setShowTermsModal(false);
    setError('');

    try {
      const email = registerForm.email.trim().toLowerCase();
      const phone = normalizePhone(registerForm.phone);
      const registerData: any = {
        email,
        password: registerForm.password,
        password_confirm: registerForm.confirmPassword,
        first_name: registerForm.firstName.trim(),
        last_name: registerForm.lastName.trim(),
        phone_number: phone,
        date_of_birth: registerForm.birthDate,
        nationality: registerForm.nationality,
        captcha: registerForm.captcha,
      };
      
      // اگر ملیت ایرانی بود، national_id بفرست، در غیر این صورت passport_number
      if (registerForm.nationality === 'iranian') {
        registerData.national_id = registerForm.nationalId;
      } else {
        registerData.passport_number = registerForm.nationalId;
      }
      
      await dispatch(registerUser(registerData)).unwrap();

      setSuccess(t('auth.registerSuccess'));
      
      // Already authenticated — stay on booking/payment, otherwise go to panel
      setTimeout(() => {
        onClose();
        if (!shouldStayOnPage) {
          navigate('/dashboard');
        }
      }, 800);
    } catch (err: any) {
      const message =
        typeof err === 'string'
          ? err
          : (err?.message || err?.payload || t('auth.registerError'));
      setError(typeof message === 'string' ? message : t('auth.registerError'));
      generateCaptcha();
      setRegisterForm((prev) => ({ ...prev, captcha: '' }));
    }
  };

  // ✨ انصراف از ثبت‌نام
  const handleCancelTerms = () => {
    setShowTermsModal(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
      ></div>

      {/* Modal */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md mx-4 max-h-[90vh] overflow-y-auto">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 left-4 p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-full transition-colors z-10"
        >
          <XMarkIcon className="w-6 h-6" />
        </button>

        {/* Header */}
        <div className="bg-gradient-to-r from-blue-900 to-blue-800 p-6 rounded-t-2xl">
          <h2 
            className="text-2xl font-bold text-white text-center"
            style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
          >
            {mode === 'login' ? t('auth.loginTitle') : t('auth.registerTitle')}
          </h2>
        </div>

        {/* Content */}
        <div className="p-6">
          {/* Error/Success Messages */}
          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-red-800 text-sm" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
              {error}
            </div>
          )}
          {success && (
            <div className="mb-4 p-3 bg-green-50 border border-green-200 rounded-lg text-green-800 text-sm" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
              {success}
            </div>
          )}

          {/* Login Form */}
          {mode === 'login' && (
            <form onSubmit={handleLogin} className="space-y-4">
              {/* نام کاربری: کد ملی / پاسپورت / یا ایمیل (برای کسانی که ایمیلشون رو عوض کردن) */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.nationalId')}
                  <span className="block text-xs font-normal text-gray-500 mt-1" style={{ direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {t('auth.foreignNationalMessage')}
                    <br />
                    {language === 'fa' ? 'یا ایمیل خود را وارد کنید (اگر در پروفایل تغییر داده‌اید)' : language === 'ar' ? 'أو أدخل بريدك الإلكتروني (إذا غيّرته في الملف الشخصي)' : 'Or enter your email (if you changed it in profile)'}
                  </span>
                </label>
                <input
                  type="text"
                  value={loginForm.nationalId}
                  onChange={(e) => {
                    const value = e.target.value;
                    // اگر حاوی @ است = ایمیل، همه کاراکترهای مجاز ایمیل رو بذار
                    if (value.includes('@')) {
                      setLoginForm(prev => ({ ...prev, nationalId: value.slice(0, 100) }));
                    } else {
                      // کد ملی یا پاسپورت: فقط حروف و اعداد
                      const cleaned = value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 20);
                      setLoginForm(prev => ({ ...prev, nationalId: cleaned }));
                    }
                  }}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: 'ltr', textAlign: 'right' }}
                  placeholder={t('auth.nationalIdOrPassportPlaceholder')}
                  maxLength={100}
                  required
                />
              </div>

              {/* Password */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.password')}
                </label>
                <div className="relative">
                  <input
                    type={showPassword ? 'text' : 'password'}
                    value={loginForm.password}
                    onChange={(e) => setLoginForm(prev => ({ ...prev, password: e.target.value }))}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
                    placeholder={t('auth.passwordPlaceholder')}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  >
                    {showPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                  </button>
                </div>
              </div>

              {/* Captcha */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.captcha')}
                </label>
                <div className="flex items-center gap-3 mb-2">
                  <div className="flex-1 bg-blue-50 border-2 border-blue-200 rounded-lg p-4 text-center" dir="ltr">
                    <span className="text-2xl font-bold text-blue-900 inline-block" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                      {captchaPrompt(captcha)}
                    </span>
                  </div>
                  <button
                    type="button"
                    onClick={generateCaptcha}
                    className="px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm"
                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                  >
                    {t('auth.captchaChange')}
                  </button>
                </div>
                <input
                  type="text"
                  inputMode="numeric"
                  value={loginForm.captcha}
                  onChange={(e) => setLoginForm(prev => ({
                    ...prev,
                    captcha: normalizeDigits(e.target.value).replace(/[^\d]/g, '').slice(0, 3),
                  }))}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                  dir="ltr"
                  placeholder={t('auth.captchaPlaceholder')}
                  required
                />
              </div>

              {/* Forgot Password Link */}
              <div className="text-center">
                <Link
                  to="/forgot-password"
                  onClick={onClose}
                  className="text-sm font-medium text-blue-600 hover:text-blue-800 transition-colors"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                >
                  {t('auth.forgotPassword')}
                </Link>
              </div>

              {/* Submit Button */}
              <button
                type="submit"
                className="w-full bg-blue-900 hover:bg-blue-800 text-white font-bold py-3 rounded-lg transition-colors"
                style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
              >
                {t('auth.loginButton')}
              </button>
            </form>
          )}

          {/* Register Form */}
          {mode === 'register' && (
            <form onSubmit={handleRegister} className="space-y-4">
              {/* Nationality */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.nationality')}
                </label>
                <CustomSelect
                  value={registerForm.nationality}
                  onChange={(value) => setRegisterForm(prev => ({ ...prev, nationality: value }))}
                  options={[
                    { value: 'iranian', label: t('nationality.iranian') },
                    { value: 'afghan', label: t('nationality.afghan') },
                    { value: 'iraqi', label: t('nationality.iraqi') },
                    { value: 'other', label: t('nationality.other') }
                  ]}
                  placeholder={t('auth.selectNationality')}
                />
              </div>

              {/* National ID / Passport Number */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {registerForm.nationality === 'iranian' 
                    ? t('auth.nationalIdRegister') 
                    : t('auth.passportNumber')}
                </label>
                <input
                  type="text"
                  value={registerForm.nationalId}
                  onChange={(e) => {
                    if (registerForm.nationality === 'iranian') {
                      // فقط اعداد و حداکثر 10 رقم برای کد ملی
                      setRegisterForm(prev => ({ ...prev, nationalId: e.target.value.replace(/\D/g, '').slice(0, 10) }));
                    } else {
                      // برای پاسپورت: حروف و اعداد، حداکثر 20 کاراکتر
                      setRegisterForm(prev => ({ ...prev, nationalId: e.target.value.toUpperCase().slice(0, 20) }));
                    }
                  }}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: registerForm.nationality === 'iranian' ? 'ltr' : 'ltr', textAlign: 'right' }}
                  placeholder={
                    registerForm.nationality === 'iranian' 
                      ? t('auth.nationalIdPlaceholder') 
                      : t('auth.passportPlaceholder')
                  }
                  maxLength={registerForm.nationality === 'iranian' ? 10 : 20}
                  required
                />
              </div>

              {/* Passenger first / last name */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {t('auth.firstName')}
                  </label>
                  <input
                    type="text"
                    value={registerForm.firstName}
                    onChange={(e) => setRegisterForm(prev => ({ ...prev, firstName: e.target.value }))}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                    placeholder={t('auth.firstNamePlaceholder')}
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {t('auth.lastName')}
                  </label>
                  <input
                    type="text"
                    value={registerForm.lastName}
                    onChange={(e) => setRegisterForm(prev => ({ ...prev, lastName: e.target.value }))}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                    placeholder={t('auth.lastNamePlaceholder')}
                    required
                  />
                </div>
              </div>

              {/* Email — required */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.email')}
                </label>
                <input
                  type="email"
                  inputMode="email"
                  autoComplete="email"
                  value={registerForm.email}
                  onChange={(e) => setRegisterForm(prev => ({ ...prev, email: e.target.value }))}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                  dir="ltr"
                  placeholder={t('auth.emailPlaceholder')}
                  required
                />
              </div>

              {/* Phone — required */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.phone')}
                </label>
                <input
                  type="tel"
                  inputMode="numeric"
                  autoComplete="tel"
                  value={registerForm.phone}
                  onChange={(e) => setRegisterForm(prev => ({
                    ...prev,
                    phone: e.target.value.replace(/[^\d+]/g, '').slice(0, 14),
                  }))}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                  dir="ltr"
                  placeholder={t('auth.phonePlaceholder')}
                  required
                />
              </div>

              {/* Birth Date */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.birthDate')}
                </label>
                <input
                  type="date"
                  value={registerForm.birthDate}
                  onChange={(e) => setRegisterForm(prev => ({ ...prev, birthDate: e.target.value }))}
                  max={new Date(new Date().setFullYear(new Date().getFullYear() - 18)).toISOString().split('T')[0]}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                  required
                />
              </div>

              {/* Password */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.password')}
                </label>
                <div className="relative">
                  <input
                    type={showPassword ? 'text' : 'password'}
                    value={registerForm.password}
                    onChange={(e) => setRegisterForm(prev => ({ ...prev, password: e.target.value }))}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
                    placeholder={t('auth.passwordPlaceholder')}
                    minLength={8}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  >
                    {showPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                  </button>
                </div>
              </div>

              {/* Confirm Password */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.confirmPassword')}
                </label>
                <div className="relative">
                  <input
                    type={showConfirmPassword ? 'text' : 'password'}
                    value={registerForm.confirmPassword}
                    onChange={(e) => setRegisterForm(prev => ({ ...prev, confirmPassword: e.target.value }))}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
                    placeholder={t('auth.confirmPasswordPlaceholder')}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  >
                    {showConfirmPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                  </button>
                </div>
              </div>

              {/* Captcha */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                  {t('auth.captcha')}
                </label>
                <div className="flex items-center gap-3 mb-2">
                  <div className="flex-1 bg-blue-50 border-2 border-blue-200 rounded-lg p-4 text-center" dir="ltr">
                    <span className="text-2xl font-bold text-blue-900 inline-block" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                      {captchaPrompt(captcha)}
                    </span>
                  </div>
                  <button
                    type="button"
                    onClick={generateCaptcha}
                    className="px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm"
                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                  >
                    {t('auth.captchaChange')}
                  </button>
                </div>
                <input
                  type="text"
                  inputMode="numeric"
                  value={registerForm.captcha}
                  onChange={(e) => setRegisterForm(prev => ({
                    ...prev,
                    captcha: normalizeDigits(e.target.value).replace(/[^\d]/g, '').slice(0, 3),
                  }))}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-900 focus:border-blue-900"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                  dir="ltr"
                  placeholder={t('auth.captchaPlaceholder')}
                  required
                />
              </div>

              {/* Submit Button */}
              <button
                type="submit"
                className="w-full bg-blue-900 hover:bg-blue-800 text-white font-bold py-3 rounded-lg transition-colors"
                style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
              >
                {t('auth.registerButton')}
              </button>
            </form>
          )}

          {/* Toggle Mode */}
          <div className="mt-6 text-center">
            <button
              onClick={() => {
                setMode(mode === 'login' ? 'register' : 'login');
                setError('');
                setSuccess('');
              }}
              className="text-blue-900 hover:text-blue-800 font-bold text-sm"
              style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
            >
              {mode === 'login' ? t('auth.noAccount') : t('auth.haveAccount')}
            </button>
          </div>
        </div>
      </div>

      {/* ✨ مودال شرایط برنامه وفاداری */}
      {showTermsModal && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[10000] flex items-center justify-center p-4"
          onClick={handleCancelTerms}
        >
          <div 
            className="bg-white/90 backdrop-blur-lg rounded-2xl shadow-2xl w-full max-w-md p-6 relative border border-white/40"
            onClick={(e) => e.stopPropagation()}
            style={{ 
              background: 'linear-gradient(145deg, rgba(255,255,255,0.92) 0%, rgba(240,248,255,0.85) 100%)',
              boxShadow: '0 10px 30px -5px rgba(0, 0, 0, 0.35)'
            }}
          >
            <div className="absolute -top-4 -right-4 w-16 h-16 bg-blue-100 rounded-full opacity-70 blur-2xl"></div>
            <div className="absolute -bottom-6 -left-6 w-24 h-24 bg-sky-100 rounded-full opacity-60 blur-3xl"></div>
            
            <div className="relative z-10">
              <div className="flex items-center mb-5 pb-3 border-b border-blue-100">
                <div className="bg-blue-600 text-white rounded-full p-2 mr-3 shadow-lg">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM4.332 8.027a6.012 6.012 0 011.912-2.706C6.512 5.73 6.974 6 7.5 6A1.5 1.5 0 019 7.5V8a2 2 0 004 0 2 2 0 011.523-1.943A5.977 5.977 0 0116 10c0 .34-.028.675-.083 1H15a2 2 0 00-2 2v2.197A5.973 5.973 0 0110 16v-2a2 2 0 00-2-2 2 2 0 01-2-2 2 2 0 00-1.668-1.973z" clipRule="evenodd" />
                  </svg>
                </div>
                <h2 className="text-xl font-bold text-gray-800" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                  شرایط برنامه وفاداری هواپیمایی نسیم
                </h2>
              </div>
              
              <div className="mb-6 max-h-60 overflow-y-auto pr-2">
                <p className="text-sm text-gray-700 leading-relaxed" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                  با ثبت‌نام در برنامه وفاداری «هواپیمایی نسیم»، شما موافقت می‌کنید که:
                </p>
                <ul className="mt-3 space-y-2 pr-3 text-sm text-gray-800" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                  <li className="flex items-start">
                    <span className="text-blue-600 ml-2 mt-1">•</span>
                    <span>اطلاعات پروازهای شما جهت محاسبه و اهدای امتیاز وفاداری توسط شرکت هواپیمایی هواپیمایی نسیم جمع‌آوری گردد.</span>
                  </li>
                  <li className="flex items-start">
                    <span className="text-blue-600 ml-2 mt-1">•</span>
                    <span>امتیازات کسب‌شده قابل استفاده برای تخفیف در خرید بلیط‌های آتی، ارتقاء کلاس پرواز و خدمات ویژه باشد.</span>
                  </li>
                  <li className="flex items-start">
                    <span className="text-blue-600 ml-2 mt-1">•</span>
                    <span>شرکت هواپیمایی نسیم متعهد به رعایت کامل حریم خصوصی شما و عدم اشتراک‌گذاری داده‌ها با سایر جهات بدون رضایت کتبی شماست.</span>
                  </li>
                  <li className="flex items-start">
                    <span className="text-blue-600 ml-2 mt-1">•</span>
                    <span>عدم پذیرش این شرایط، امکان عضویت در برنامه وفاداری را منتفی می‌سازد.</span>
                  </li>
                </ul>
                <p className="mt-4 text-xs text-gray-500 italic" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                  این موارد مطابق با قوانین هواپیمایی جمهوری اسلامی ایران و مقررات بین‌المللی حفظ حریم خصوصی تنظیم شده است.
                </p>
              </div>
              
              <div className="flex justify-between gap-3 pt-4 border-t border-blue-50">
                <button
                  type="button"
                  onClick={handleCancelTerms}
                  className="flex-1 py-2.5 px-4 border border-gray-300 rounded-xl text-gray-700 font-medium hover:bg-gray-50 transition-all duration-200"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                >
                  انصراف
                </button>
                <button
                  type="button"
                  onClick={mode === 'login' ? handleAgreeLoginTerms : handleAgreeTerms}
                  disabled={!!error}
                  className={`flex-1 py-2.5 px-4 rounded-xl font-medium text-white transition-all duration-200 ${
                    error 
                      ? 'bg-gray-400 cursor-not-allowed' 
                      : 'bg-gradient-to-r from-blue-600 to-sky-600 hover:from-blue-700 hover:to-sky-700 shadow-lg hover:shadow-xl'
                  }`}
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                >
                  {error ? 'در حال پردازش...' : 'موافقم و ادامه می‌دهم'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AuthModal;